package api

import (
	"errors"
	"net/http"
	"strconv"
	"strings"
	"time"
	"github.com/eutelic/runnerhub/internal/core"
)

type scaleSetStatusResponse struct{PoolID string `json:"poolId"`;State string `json:"state"`;Detail string `json:"detail,omitempty"`;UpdatedAt time.Time `json:"updatedAt"`}
type scaleSetStatusRequest struct{PoolID string `json:"poolId"`;State string `json:"state"`;Detail string `json:"detail,omitempty"`}
func(s *Service)setScaleSetStatus(poolID,state,detail string)(scaleSetStatusResponse,bool){v:=scaleSetStatusResponse{PoolID:strings.TrimSpace(poolID),State:strings.TrimSpace(state),Detail:truncate(strings.TrimSpace(detail)),UpdatedAt:time.Now().UTC()};s.scaleSetStatusMu.Lock();if s.scaleSetStatuses==nil{s.scaleSetStatuses=map[string]scaleSetStatusResponse{}};prev,ok:=s.scaleSetStatuses[v.PoolID];changed:=!ok||prev.State!=v.State||prev.Detail!=v.Detail;s.scaleSetStatuses[v.PoolID]=v;s.scaleSetStatusMu.Unlock();return v,changed}
func(s *Service)scaleSetStatus(w http.ResponseWriter,r *http.Request){if r.Method==http.MethodGet{s.scaleSetStatusMu.RLock();out:=make([]scaleSetStatusResponse,0,len(s.scaleSetStatuses));for _,v:=range s.scaleSetStatuses{out=append(out,v)};s.scaleSetStatusMu.RUnlock();writeJSON(w,200,out);return};var in scaleSetStatusRequest;if !decode(w,r,&in){return};in.PoolID=strings.TrimSpace(in.PoolID);in.State=strings.ToLower(strings.TrimSpace(in.State));if in.PoolID==""{problem(w,400,errors.New("poolId is required"));return};switch in.State{case "pending","starting","ready","backing_off","error":default:problem(w,400,errors.New("invalid scale-set state"));return};if _,err:=s.Store.GetPool(r.Context(),in.PoolID);err!=nil{problem(w,404,errors.New("runner pool not found"));return};v,changed:=s.setScaleSetStatus(in.PoolID,in.State,in.Detail);if changed{_=s.Store.AppendAudit(r.Context(),core.AuditEvent{Actor:actor(r.Context()),Action:"scaleset_status",ResourceType:"pool",ResourceID:in.PoolID,Result:in.State,SafeDetail:v.Detail})};writeJSON(w,200,v)}
type scaleSetConfigResponse struct{RegistrationURL string `json:"registrationUrl"`;Name string `json:"name"`;Labels []string `json:"labels,omitempty"`;RunnerGroup string `json:"runnerGroup,omitempty"`;PoolID string `json:"poolId"`;MinRunners int `json:"minRunners"`;MaxRunners int `json:"maxRunners"`;AppInstallationID int64 `json:"appInstallationId"`}
func(s *Service)scaleSetConfigs(w http.ResponseWriter,r *http.Request){pools,err:=s.Store.ListPools(r.Context());if err!=nil{problem(w,500,err);return};out:=[]scaleSetConfigResponse{};for _,p:=range pools{if p.Scope.Kind!=core.ScopeRepository{continue};if p.ScaleSetDisabled{detail:="scale set is disabled; re-enable this publisher or profile to register its listener";status,changed:=s.setScaleSetStatus(p.ID,"disabled",detail);if changed{_=s.Store.AppendAudit(r.Context(),core.AuditEvent{Actor:"control",Action:"scaleset_configuration",ResourceType:"pool",ResourceID:p.ID,Result:"disabled",SafeDetail:status.Detail})};continue};if p.GitHubInstallationID<=0{detail:="GitHub App installation mapping is missing; reconnect this repository to register its scale set";status,changed:=s.setScaleSetStatus(p.ID,"error",detail);if changed{_=s.Store.AppendAudit(r.Context(),core.AuditEvent{Actor:"control",Action:"scaleset_configuration",ResourceType:"pool",ResourceID:p.ID,Result:"error",SafeDetail:status.Detail})};continue};name:=strings.TrimSpace(p.ScaleSetName);if name==""{name="runnerhub"};out=append(out,scaleSetConfigResponse{RegistrationURL:"https://github.com/"+p.Scope.Owner+"/"+p.Scope.Repository,Name:name,Labels:p.Labels,PoolID:p.ID,MinRunners:p.MinIdle,MaxRunners:p.MaxConcurrency,AppInstallationID:p.GitHubInstallationID})};writeJSON(w,200,out)}
func(s *Service)runnerGroups(w http.ResponseWriter,r *http.Request){if s.Catalog==nil{problem(w,503,errors.New("github catalog is not configured"));return};v,err:=s.Catalog.ListRunnerGroups(r.Context(),r.URL.Query().Get("org"));if err!=nil{problem(w,502,err);return};writeJSON(w,200,v)}
func(s *Service)audit(w http.ResponseWriter,r *http.Request){limit,_:=strconv.Atoi(r.URL.Query().Get("limit"));v,err:=s.Store.ListAudit(r.Context(),limit);if err!=nil{problem(w,500,err);return};writeJSON(w,200,v)}
func(s *Service)metrics(w http.ResponseWriter,_ *http.Request){if s.Metrics==nil{writeJSON(w,200,map[string]int{});return};writeJSON(w,200,s.Metrics.Snapshot())}
